1	package keymap
2	
3	import (
4		"go/ast"
5		"go/parser"
6		"go/token"
7		"io/fs"
8		"path/filepath"
9		"slices"
10		"strconv"
11		"strings"
12		"testing"
13	)
14	
15	// The vocabulary only matters if it is checked against the code. These
16	// tests do that: they scan the views' sources and verify that what they
17	// bind is indeed what this package declares. A source scan is fragile, and
18	// that is accepted — it is the price of the check, and internal/command
19	// already has this kind of contract test
20	// (TestEveryViewSuppliesItsHeaderAndHelp).
21	
22	// scannedTrees are the trees where key bindings live.
23	var scannedTrees = []string{
24		filepath.Join("..", "..", "app"),
25		filepath.Join("..", ".."),
26	}
27	
28	// structuralKeys are the keys whose meaning never changes. Their presence
29	// in a switch is what lets one recognize a key switch without relying on
30	// the name of the tested variable: a switch on runtime.GOOS or on a
31	// severity contains none of them.
32	var structuralKeys = map[string]bool{
33		"esc": true, "enter": true, "tab": true, "shift+tab": true,
34		"up": true, "down": true, "left": true, "right": true,
35		"pgup": true, "pgdown": true, "home": true, "end": true,
36		" ": true, "/": true, "?": true,
37	}
38	
39	// navigationKeys are the ones whose lettered alias would be navigation.
40	var navigationKeys = map[string]bool{
41		"up": true, "down": true, "left": true, "right": true,
42		"pgup": true, "pgdown": true, "home": true, "end": true,
43	}
44	
45	// retiredAliases have no surviving meaning in the application: neither an
46	// action (they are lowercase) nor a declared toggle. Encountering them in
47	// a key switch can only be a vim leftover.
48	//
49	// `h`, `l` and `f` are not in it: they survive as local toggles (HIGH and
50	// LOW severity in security, protocol in netdiag, format in the viewer).
51	// It's the clause that gives them away, not the letter — see
52	// TestNoBareLetterIsNavigation.
53	//
54	// `g` left this list with §3.53, and the reason is the one that brought
55	// `H` back into `free` in §3.47, taken the other way round: a letter that
56	// regains a meaning leaves the list of those that no longer have one,
57	// otherwise the list would lie. What it means in the viewer is not what
58	// §3.26 took away from it — it opens a prompt, and the jump takes an
59	// **argument**, which `home` and `end` do not and never will cover. `j`
60	// and `k` remain retired: they are only `down` and `up` under another
61	// name.
62	var retiredAliases = map[string]bool{"j": true, "k": true}
63	
64	func TestEveryActionIsOneUppercaseLetter(t *testing.T) {
65		for key, meaning := range actions {
66			if len([]rune(key)) != 1 || key < "A" || key > "Z" {
67				t.Errorf("action %q (%s) is not a single uppercase letter; the whole "+
68					"namespace rule rests on that shape", key, meaning)
69			}
70			if strings.TrimSpace(meaning) == "" {
71				t.Errorf("action %q carries no meaning", key)
72			}
73		}
74	}
75	
76	// TestFreeLettersAreActuallyFree keeps the list of available letters from
77	// lying. It exists so the next addition doesn't have to redo the survey,
78	// so a stale entry is worse than no list at all.
79	func TestFreeLettersAreActuallyFree(t *testing.T) {
80		for _, key := range Free() {
81			if IsAction(key) {
82				t.Errorf("%q is advertised as free but %s already claims it", key, actions[key])
83			}
84		}
85		if got := len(actions) + len(free); got != 26 {
86			t.Errorf("actions + free = %d, want 26 — a letter is either used or free, "+
87				"and one that is neither is a letter nobody knows about", got)
88		}
89	}
90	
91	// TestNoLocalToggleShadowsAnAction verifies that the two namespaces stay
92	// disjoint. They are disjoint by case, but a toggle declared in uppercase
93	// by mistake would silently merge them back together.
94	func TestNoLocalToggleShadowsAnAction(t *testing.T) {
95		for _, surface := range localToggles {
96			for _, key := range surface.Keys {
97				if key != strings.ToLower(key) {
98					t.Errorf("%s declares %q as a toggle, but it is not lowercase; "+
99						"a toggle changes nothing and an action does", surface.Name, key)
100				}
101			}
102		}
103	}
104	
105	// TestNoViewBindsAnUndeclaredUppercaseKey is the central test: any uppercase
106	// letter bound in a view must come from the vocabulary. It's this test that
107	// turns "keys should be consistent" into something that fails the build.
108	func TestNoViewBindsAnUndeclaredUppercaseKey(t *testing.T) {
109		for _, clause := range keySwitchClauses(t) {
110			for _, key := range clause.keys {
111				if len([]rune(key)) != 1 || key < "A" || key > "Z" {
112					continue
113				}
114				if IsAction(key) {
115					continue
116				}
117				// A modal is a mode: it claims every key before the view sees
118				// it, so its Y/N cannot collide with any action.
119				if IsModalKey(key) && clause.isModal {
120					continue
121				}
122				t.Errorf("%s: binds %q, which no action declares.\n"+
123					"An uppercase letter is an action and its meaning is global "+
124					"(internal/ui/keymap). Either reuse the action that already means "+
125					"this, or add it there — free letters: %v",
126					clause.where, key, Free())
127			}
128		}
129	}
130	
131	// TestNoBareLetterIsNavigation is the rule bought by removing the vim
132	// aliases, and the only thing it buys.
133	//
134	// Two forms violate it. An alias — a letter in the same clause as a
135	// navigation key, `case "up", "k"` — and an isolated leftover, `case "j"`.
136	// The first is what made the rule unverifiable; keeping j/k alone would
137	// leave an exception, and it is exceptions that produced the state §3.26
138	// found.
139	func TestNoBareLetterIsNavigation(t *testing.T) {
140		for _, clause := range keySwitchClauses(t) {
141			hasNavigation := false
142			for _, key := range clause.keys {
143				if navigationKeys[key] {
144					hasNavigation = true
145				}
146			}
147	
148			for _, key := range clause.keys {
149				if len([]rune(key)) != 1 || !isLetter(key) {
150					continue
151				}
152				if retiredAliases[key] {
153					t.Errorf("%s: binds %q, a vim alias with no surviving meaning "+
154						"(home/end already cover g/G)", clause.where, key)
155					continue
156				}
157				if hasNavigation {
158					t.Errorf("%s: binds %q alongside navigation keys %v — no bare "+
159						"letter is navigation", clause.where, key, clause.keys)
160				}
161			}
162		}
163	}
164	
165	// TestOnlyThreeCtrlCombinationsSurvive: the Ctrl budget is ~14 keys and
166	// each one drags a constraint (multiplexer prefix, flow control, tty
167	// character). §3.26 keeps only three, and any action that resettled
168	// behind Ctrl would retake a spot Shift gives for free.
169	func TestOnlyThreeCtrlCombinationsSurvive(t *testing.T) {
170		survivors := map[string]string{
171			"ctrl+c": "SIGINT — quitter",
172			"ctrl+r": "rafraîchir, et rien d'autre",
173			"ctrl+p": "la ligne de commande",
174		}
175		for _, clause := range keySwitchClauses(t) {
176			for _, key := range clause.keys {
177				if !strings.HasPrefix(key, "ctrl+") {
178					continue
179				}
180				if _, ok := survivors[key]; ok {
181					continue
182				}
183				if IsException(key) {
184					continue
185				}
186				t.Errorf("%s: binds %q.\n"+
187					"Only ctrl+c, ctrl+r and ctrl+p survive; an action belongs to the "+
188					"uppercase vocabulary (internal/ui/keymap). Declared exceptions: %v",
189					clause.where, key, exceptionKeys())
190			}
191		}
192	}
193	
194	// TestEveryLowercaseBindingIsDeclared: a lowercase letter changes nothing,
195	// so its meaning can be local — but "local" must mean declared, otherwise
196	// it's just "not surveyed", which is the state we're coming from.
197	func TestEveryLowercaseBindingIsDeclared(t *testing.T) {
198		// What holds everywhere: modal shortcuts, declared exceptions, and
199		// `q` — which the router owns and no view binds.
200		everywhere := map[string]bool{"q": true}
201		for key := range modalKeys {
202			everywhere[key] = true
203		}
204		for _, e := range exceptions {
205			everywhere[e.Key] = true
206		}
207	
208		for _, clause := range keySwitchClauses(t) {
209			surface, hasSurface := SurfaceFor(clause.where)
210	
211			for _, key := range clause.keys {
212				if len([]rune(key)) != 1 || key < "a" || key > "z" {
213					continue
214				}
215				if everywhere[key] || (hasSurface && slices.Contains(surface.Keys, key)) {
216					continue
217				}
218				where := "no surface"
219				if hasSurface {
220					where = surface.Name + " (" + strings.Join(surface.Keys, " ") + ")"
221				}
222				t.Errorf("%s: binds %q, which %s declares.\n"+
223					"A lowercase letter is a filter or a display toggle and changes "+
224					"nothing; if it acts, it is an action and belongs in uppercase. "+
225					"Declare it on the surface or move it (internal/ui/keymap).",
226					clause.where, key, where)
227			}
228		}
229	}
230	
231	// TestTheCommandModeKeyIsReachable keeps the reason for the choice with
232	// the choice. alt+: was just as valid, until it turned out it didn't
233	// reach macOS; what was missing wasn't a test but the list of what needed
234	// to be ruled out.
235	func TestTheCommandModeKeyIsReachable(t *testing.T) {
236		forbidden := map[string]string{
237			"ctrl+:": "\":\" is 0x3A, outside the 0x40-0x5F range Ctrl encodes",
238			"alt+:":  "Option is not Meta on macOS Terminal.app or iTerm2 by default",
239			"ctrl+a": "screen's prefix",
240			"ctrl+b": "tmux's prefix",
241			"ctrl+c": "SIGINT",
242			"ctrl+d": "EOF",
243			"ctrl+s": "flow control (XOFF)",
244			"ctrl+q": "flow control (XON)",
245			"ctrl+i": "TAB",
246			"ctrl+m": "Enter",
247			"ctrl+j": "LF",
248			"ctrl+h": "Backspace",
249		}
250		if why, bad := forbidden[CommandMode]; bad {
251			t.Fatalf("CommandMode is %q, which cannot reach the application: %s", CommandMode, why)
252		}
253	}
254	
255	// --- source scan ---
256	
257	type caseClause struct {
258		where string
259		keys  []string
260		// isModal marks a clause belonging to a modal's switch, recognized by
261		// the fact that it binds y and n in lowercase. A modal is a mode, not
262		// a view: it takes over before the view sees anything.
263		isModal bool
264	}
265	
266	// keySwitchClauses returns every key-switch clause from the views.
267	//
268	// A switch is recognized as being about keys when one of its clauses
269	// cites a structural key or a ctrl+/alt+ combination. This is safer than
270	// relying on the name of the tested expression: msg.String() is not the
271	// only form, and a switch on runtime.GOOS or on a severity contains none
272	// of these strings.
273	func keySwitchClauses(t *testing.T) []caseClause {
274		t.Helper()
275	
276		seen := map[string]bool{}
277		var clauses []caseClause
278	
279		for _, root := range scannedTrees {
280			err := filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
281				if err != nil {
282					return err
283				}
284				if d.IsDir() || !strings.HasSuffix(path, ".go") || strings.HasSuffix(path, "_test.go") {
285					return nil
286				}
287				// This package declares the vocabulary; it necessarily cites it.
288				if strings.Contains(filepath.ToSlash(path), "internal/ui/keymap/") {
289					return nil
290				}
291				if seen[path] {
292					return nil
293				}
294				seen[path] = true
295	
296				fset := token.NewFileSet()
297				file, err := parser.ParseFile(fset, path, nil, 0)
298				if err != nil {
299					t.Fatalf("parse %s: %v", path, err)
300				}
301	
302				ast.Inspect(file, func(n ast.Node) bool {
303					sw, ok := n.(*ast.SwitchStmt)
304					if !ok || sw.Body == nil {
305						return true
306					}
307					parsed := clausesOf(sw, fset, path)
308					if !isKeySwitch(parsed) {
309						return true
310					}
311					if isModalSwitch(parsed) {
312						for i := range parsed {
313							parsed[i].isModal = true
314						}
315					}
316					clauses = append(clauses, parsed...)
317					return true
318				})
319				return nil
320			})
321			if err != nil {
322				t.Fatalf("walk %s: %v", root, err)
323			}
324		}
325	
326		if len(clauses) == 0 {
327			t.Fatal("no key switch found — the scan is broken, not the code")
328		}
329		return clauses
330	}
331	
332	func clausesOf(sw *ast.SwitchStmt, fset *token.FileSet, path string) []caseClause {
333		var out []caseClause
334		for _, stmt := range sw.Body.List {
335			cc, ok := stmt.(*ast.CaseClause)
336			if !ok || len(cc.List) == 0 {
337				continue
338			}
339			var keys []string
340			for _, expr := range cc.List {
341				lit, ok := expr.(*ast.BasicLit)
342				if !ok || lit.Kind != token.STRING {
343					continue
344				}
345				value, err := strconv.Unquote(lit.Value)
346				if err != nil {
347					continue
348				}
349				keys = append(keys, value)
350			}
351			if len(keys) == 0 {
352				continue
353			}
354			position := fset.Position(cc.Pos())
355			out = append(out, caseClause{
356				where: filepath.ToSlash(path) + ":" + strconv.Itoa(position.Line),
357				keys:  keys,
358			})
359		}
360		return out
361	}
362	
363	func isKeySwitch(clauses []caseClause) bool {
364		for _, clause := range clauses {
365			for _, key := range clause.keys {
366				if structuralKeys[key] ||
367					strings.HasPrefix(key, "ctrl+") ||
368					strings.HasPrefix(key, "alt+") ||
369					strings.HasPrefix(key, "shift+") {
370					return true
371				}
372			}
373		}
374		return false
375	}
376	
377	// isModalSwitch recognizes a confirmation modal's switch by the fact that
378	// it binds y and n in lowercase — which no view does.
379	func isModalSwitch(clauses []caseClause) bool {
380		var yes, no bool
381		for _, clause := range clauses {
382			for _, key := range clause.keys {
383				switch key {
384				case "y":
385					yes = true
386				case "n":
387					no = true
388				}
389			}
390		}
391		return yes && no
392	}
393	
394	func exceptionKeys() []string {
395		out := make([]string, 0, len(exceptions))
396		for _, e := range exceptions {
397			out = append(out, e.Key+" ("+e.Surface+")")
398		}
399		return out
400	}
