1	package keymap
2	
3	import (
4		"go/ast"
5		"go/parser"
6		"go/token"
7		"io/fs"
8		"path/filepath"
9		"sort"
10		"strconv"
11		"strings"
12		"testing"
13	)
14	
15	// D63 — an announced key that does nothing.
16	//
17	// Rule 130 forbids a *greyed-out* key that acts anyway, and
18	// shortcut.Availability makes that inexpressible: one field, two readers.
19	// Nothing guarded against the opposite sense, and the security view carried
20	// two instances of it in the same state — `{Key: "o"}` announced while the
21	// handler read `case keymap.Web:`, and `{Key: "esc/⌫"}` while it only read
22	// `case "esc":`. In both cases the displayed key did nothing, and the one
23	// that worked was never shown.
24	//
25	// No test could see them, and the reason is structural: **the announced
26	// key is a display string, the bound key is a bubbletea key name**, and
27	// there is no mechanical relation between the two. `↑↓` is bound via
28	// `case "up"`, `esc/⌫` via `case "esc"`. A test that naively matched
29	// `{Key: …}` against `case …:` would mostly produce noise — a crude survey
30	// turns up 52 candidates, the overwhelming majority of which are help
31	// labels (`Context`, `Images`, `Disk Usage`).
32	//
33	// What closes the family is therefore to **create** the relation where it
34	// can exist: a key from the vocabulary is announced by the same token the
35	// handler tests. This is what the fix for the `o` instance had already
36	// done by hand with `openPipelineKey`, and these three tests turn that
37	// into a build constraint rather than a good practice.
38	//
39	// What is not covered, and deliberately so: `↑↓`, `esc/⌫`, `enter/esc`,
40	// `tab / shift+tab`. These are display strings with no mechanical relation
41	// to anything, and Rule 138 already keeps most of them off the screen.
42	// Guessing there would produce the 52 candidates.
43	//
44	// The granularity is the **package**, not the view's state. A key bound in
45	// one tab and announced in another therefore passes, and that is the price
46	// of a source scan: knowing in which state a clause applies would require
47	// driving the view. What these tests catch is the key bound *nowhere*,
48	// which is what the two reported instances were.
49	
50	// TestNoAnnouncementSpellsAnActionOutInFull is the half that makes the other
51	// two possible: a Key written "S" is a string like any other, and nothing can
52	// tell it from a help label. Written keymap.Scan, it is the same token the
53	// handler tests.
54	func TestNoAnnouncementSpellsAnActionOutInFull(t *testing.T) {
55		for _, a := range announcements(t) {
56			if a.constant != "" || !IsAction(a.key) {
57				continue
58			}
59			t.Errorf("%s: announces %q as a bare letter.\n"+
60				"Write it as keymap.%s — an announcement and its binding have no "+
61				"mechanical relation unless they are the same token, and that is "+
62				"the whole of §1.3 D63.",
63				a.where, a.key, actionName(a.key))
64		}
65	}
66	
67	// TestEveryAnnouncedActionIsBoundInItsPackage is the check itself: a view that
68	// shows `S Scan` must answer keymap.Scan somewhere in the same package.
69	//
70	// The package rather than the file, because a view's shortcuts and its handler
71	// are deliberately apart — availability.go, view.go, update.go.
72	func TestEveryAnnouncedActionIsBoundInItsPackage(t *testing.T) {
73		bound := bindings(t)
74	
75		for _, a := range announcements(t) {
76			if a.constant == "" || !IsAction(actionValue(a.constant)) {
77				// keymap.CommandMode is announced by views the router answers for,
78				// and it is the only constant here that is not an action.
79				continue
80			}
81			if bound[a.pkg][a.constant] {
82				continue
83			}
84			t.Errorf("%s: announces keymap.%s, which nothing in %s binds.\n"+
85				"A key that is shown and does nothing is worse than one that is "+
86				"absent: the user reaches for it, and the key that works is never "+
87				"advertised. Bound here: %v",
88				a.where, a.constant, a.pkg, sortedKeys(bound[a.pkg]))
89		}
90	}
91	
92	// TestEveryAnnouncedToggleIsBoundInItsPackage closes the family on the half the
93	// vocabulary cannot name.
94	//
95	// A lowercase toggle has no constant — its meaning is local by design — but it
96	// is still a single letter, so the announcement and the binding *can* be the
97	// same string and the comparison is exact rather than noisy. This is the test
98	// that would have caught the reported instance: security announced
99	// `{Key: "o"}` while its handler read `case keymap.Web:`.
100	func TestEveryAnnouncedToggleIsBoundInItsPackage(t *testing.T) {
101		bound := bindings(t)
102	
103		for _, a := range announcements(t) {
104			if len([]rune(a.key)) != 1 || a.key < "a" || a.key > "z" {
105				continue
106			}
107			if bound[a.pkg][a.key] {
108				continue
109			}
110			t.Errorf("%s: announces %q, which nothing in %s binds.\n"+
111				"Either bind it, or advertise the key that actually does this — "+
112				"a key shown and dead is what §1.3 D63 is. Bound here: %v",
113				a.where, a.key, a.pkg, sortedKeys(bound[a.pkg]))
114		}
115	}
116	
117	// --- source scan ---
118	
119	// announcement is one `{Key: …, Description: …}` found in the sources.
120	//
121	// The pair of fields *is* the recogniser, rather than the type name: both
122	// shortcut.Shortcut and help.KeyBinding carry it, an element inside a slice
123	// literal has no type to read, and shortcut.HeaderInfo — the one other thing
124	// with a Key — has Value where these have Description.
125	type announcement struct {
126		where string
127		pkg   string
128		// key is the key as a string, whether it was written as a literal or as a
129		// package constant. constant is set instead when the Key is keymap.X, since
130		// those are compared as constants rather than as text.
131		key      string
132		constant string
133	}
134	
135	func announcements(t *testing.T) []announcement {
136		t.Helper()
137	
138		consts := stringConstants(t)
139		var out []announcement
140	
141		forEachSourceFile(t, func(path string, fset *token.FileSet, file *ast.File) {
142			pkg := packageDir(path)
143			ast.Inspect(file, func(n ast.Node) bool {
144				lit, ok := n.(*ast.CompositeLit)
145				if !ok {
146					return true
147				}
148				value, hasKey := fieldValue(lit, "Key")
149				if _, hasDesc := fieldValue(lit, "Description"); !hasKey || !hasDesc {
150					return true
151				}
152	
153				a := announcement{
154					where: filepath.ToSlash(path) + ":" + strconv.Itoa(fset.Position(lit.Pos()).Line),
155					pkg:   pkg,
156				}
157				switch v := value.(type) {
158				case *ast.BasicLit:
159					a.key = unquoted(v)
160				case *ast.Ident:
161					// A shared constant is how the reported instance was fixed by
162					// hand: one token, both sides. Resolving it here is what makes
163					// that pattern checkable rather than merely tidy.
164					a.key = consts[pkg][v.Name]
165				case *ast.SelectorExpr:
166					if p, ok := v.X.(*ast.Ident); ok && p.Name == "keymap" {
167						a.constant = v.Sel.Name
168					}
169				}
170				if a.key != "" || a.constant != "" {
171					out = append(out, a)
172				}
173				return true
174			})
175		})
176	
177		if len(out) == 0 {
178			t.Fatal("no shortcut or help entry found — the scan is broken, not the code")
179		}
180		return out
181	}
182	
183	// bindings maps a package directory to everything its case clauses answer:
184	// keymap constant names and plain key strings alike, in one set. The two
185	// namespaces cannot collide — a constant name is never a key string.
186	func bindings(t *testing.T) map[string]map[string]bool {
187		t.Helper()
188	
189		consts := stringConstants(t)
