1	package components
2	
3	import (
4		"strings"
5	
6		"github.com/charmbracelet/bubbles/textinput"
7		tea "github.com/charmbracelet/bubbletea"
8	
9		"github.com/anthnel/devdesk/internal/ui/theme"
10	)
11	
12	// FilterToken is a named toggle filter that can be active or inactive.
13	// Active tokens are shown as highlighted labels in the filter bar.
14	type FilterToken struct {
15		Label  string
16		Active bool
17	}
18	
19	// FilterBar is a single-line bar rendered at the bottom of a table viewport.
20	// It is hidden when no filter is active and appears automatically when:
21	//   - A toggle filter token is activated
22	//   - The user presses "/" to enter search mode
23	//
24	// Usage:
25	//
26	//	fb := components.NewFilterBar()
27	//	// or with toggle tokens:
28	//	fb := components.NewFilterBarWithTokens([]components.FilterToken{
29	//	    {Label: "tcp"}, {Label: "udp"},
30	//	})
31	//
32	// In resize: tableHeight := height - fb.ExtraHeight()
33	// In view:   append fb.View() as the last line after the table
34	// In update: forward keys to fb.Update(msg) when fb.InEditMode()
35	type FilterBar struct {
36		searching   bool
37		searchInput textinput.Model
38		searchQuery string
39		tokens      []FilterToken
40		width       int
41	}
42	
43	// NewFilterBar creates a FilterBar with no toggle tokens (text search only).
44	func NewFilterBar() FilterBar {
45		return newFilterBar(nil)
46	}
47	
48	// NewFilterBarWithTokens creates a FilterBar with the given toggle tokens.
49	func NewFilterBarWithTokens(tokens []FilterToken) FilterBar {
50		return newFilterBar(tokens)
51	}
52	
53	func newFilterBar(tokens []FilterToken) FilterBar {
54		si := textinput.New()
55		theme.StyleTextInput(&si)
56		si.CharLimit = 100
57	
58		fb := FilterBar{
59			searchInput: si,
60		}
61		if len(tokens) > 0 {
62			fb.tokens = make([]FilterToken, len(tokens))
63			copy(fb.tokens, tokens)
64		}
65		return fb
66	}
67	
68	// IsVisible returns true when the bar should be rendered (searching, query set, or any token active).
69	func (fb *FilterBar) IsVisible() bool {
70		if fb.searching || fb.searchQuery != "" {
71			return true
72		}
73		for _, t := range fb.tokens {
74			if t.Active {
75				return true
76			}
77		}
78		return false
79	}
80	
81	// ExtraHeight returns 2 when the bar is visible (1 separator + 1 bar), 0 otherwise.
82	// Subtract this from the table height so the bar doesn't overlap table rows.
83	func (fb *FilterBar) ExtraHeight() int {
84		if fb.IsVisible() {
85			return 2
86		}
87		return 0
88	}
89	
90	// Resize updates the display width used when rendering.
91	func (fb *FilterBar) Resize(width int) {
92		fb.width = width
93	}
94	
95	// InEditMode returns true when the search input is focused.
96	// Views must propagate this via their own InEditMode() to block command mode.
97	func (fb *FilterBar) InEditMode() bool {
98		return fb.searching
99	}
100	
101	// SearchQuery returns the current confirmed search string.
102	func (fb *FilterBar) SearchQuery() string {
103		return fb.searchQuery
104	}
105	
106	// ActivateSearch focuses the search input and returns the blink command.
107	func (fb *FilterBar) ActivateSearch() tea.Cmd {
108		fb.searching = true
109		fb.searchInput.Focus()
110		return textinput.Blink
111	}
112	
113	// ClearSearch clears the search query and blurs the input.
114	func (fb *FilterBar) ClearSearch() {
115		fb.searching = false
116		fb.searchQuery = ""
117		fb.searchInput.SetValue("")
118		fb.searchInput.Blur()
119	}
120	
121	// IsTokenActive returns true if the token with the given label is active.
122	func (fb *FilterBar) IsTokenActive(label string) bool {
123		for _, t := range fb.tokens {
124			if t.Label == label {
125				return t.Active
126			}
127		}
128		return false
129	}
130	
131	// SetTokenActive sets the active state of the token with the given label.
132	func (fb *FilterBar) SetTokenActive(label string, active bool) {
133		for i, t := range fb.tokens {
134			if t.Label == label {
135				fb.tokens[i].Active = active
136				return
137			}
138		}
139	}
140	
141	// SetTokens replaces the token list. Active state is preserved for tokens
142	// whose label matches an existing active token.
143	func (fb *FilterBar) SetTokens(tokens []FilterToken) {
144		activeLabels := make(map[string]bool)
145		for _, t := range fb.tokens {
146			if t.Active {
147				activeLabels[t.Label] = true
148			}
149		}
150		fb.tokens = make([]FilterToken, len(tokens))
151		copy(fb.tokens, tokens)
152		for i, t := range fb.tokens {
153			if activeLabels[t.Label] {
154				fb.tokens[i].Active = true
155			}
156		}
157	}
158	
159	// Update handles key messages when the bar is in search mode.
160	// It returns the updated FilterBar and a Bubble Tea command.
161	// Call this from the view's Update() when fb.InEditMode() is true.
162	func (fb *FilterBar) Update(msg tea.Msg) (FilterBar, tea.Cmd) {
163		if !fb.searching {
164			return *fb, nil
165		}
166		keyMsg, ok := msg.(tea.KeyMsg)
167		if !ok {
168			return *fb, nil
169		}
170		switch keyMsg.String() {
171		case "esc":
172			fb.searching = false
173			fb.searchQuery = ""
174			fb.searchInput.SetValue("")
175			fb.searchInput.Blur()
176			return *fb, nil
177		case "enter":
178			fb.searching = false
179			fb.searchQuery = fb.searchInput.Value()
180			fb.searchInput.Blur()
181			return *fb, nil
182		}
183		var cmd tea.Cmd
184		fb.searchInput, cmd = fb.searchInput.Update(msg)
185		fb.searchQuery = fb.searchInput.Value()
